import (
        "encoding/json"
        "path/filepath"
)

func writeManifest(path string, m manifestOutput) ([]byte, error) {
        data, err := json.MarshalIndent(m, "", "  ")
        if err != nil {
                return nil, err
        }
        data = append(data, '\n')
        if err := atomicWriteFile(path, data); err != nil {
                return nil, err
        }
        return data, nil
}

func writeSignature(path, manifestPath string, manifestData []byte, maxTs *string) error {
        sig := signatureOutput{
                ManifestPath:   filepath.Base(manifestPath),
                ManifestSHA256: sha256Hex(manifestData),
                ManifestBytes:  int64(len(manifestData)),
                SignedAtUTC:    signedAt(maxTs),
                ToolVersion:    toolVersion,
        }
        data, err := json.MarshalIndent(sig, "", "  ")
        if err != nil {
                return err
        }
        data = append(data, '\n')
        return atomicWriteFile(path, data)
}

func signedAt(maxTs *string) string {
        if maxTs != nil {
                return *maxTs
        }
        return "1970-01-01T00:00:00Z"
}
